def factorize(n):
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def get_divisors(factors):
    divisors = [1]
    for p, exp in factors.items():
        new_divs = []
        for d in divisors:
            for i in range(1, exp+1):
                new_divs.append(d * (p ** i))
        divisors += new_divs
    return sorted(set(divisors))

def mobius(d, factors_dict):
    mu = 1
    temp = d
    for p in factors_dict:
        if temp % p == 0:
            count = 0
            while temp % p == 0:
                count += 1
                temp //= p
            if count > 1:
                return 0
            mu *= -1
    return mu

