def main():
    data = sys.stdin.read().splitlines()
    n = int(data[0])
    s = data[1].strip()

    N = n + 10
    text = ['a'] * N
    cursor = 0

    class SegmentNode:
        __slots__ = ('total', 'min_pref', 'max_pref')
        def __init__(self, total, min_pref, max_pref):
            self.total = total
            self.min_pref = min_pref
            self.max_pref = max_pref

    size = 1
    while size < N:
        size *= 2
    seg_tree = [None] * (2 * size)

    def get_val(c):
        if c == '(':
            return 1
        elif c == ')':
            return -1
        else:
            return 0

    def build_tree(idx, l, r):
        if l == r:
            val = get_val(text[l])
            seg_tree[idx] = SegmentNode(val, val, val)
            return
        mid = (l + r) // 2
        build_tree(2*idx, l, mid)
        build_tree(2*idx+1, mid+1, r)
        left = seg_tree[2*idx]
        right = seg_tree[2*idx+1]
        total = left.total + right.total
        min_pref = min(left.min_pref, left.total + right.min_pref)
        max_pref = max(left.max_pref, left.total + right.max_pref)
        seg_tree[idx] = SegmentNode(total, min_pref, max_pref)

    def update_tree(pos, l, r, idx):
        if l == r:
            val = get_val(text[l])
            seg_tree[idx] = SegmentNode(val, val, val)
            return
        mid = (l + r) // 2
        if pos <= mid:
            update_tree(pos, l, mid, 2*idx)
        else:
            update_tree(pos, mid+1, r, 2*idx+1)
        left = seg_tree[2*idx]
        right = seg_tree[2*idx+1]
        total = left.total + right.total
        min_pref = min(left.min_pref, left.total + right.min_pref)
        max_pref = max(left.max_pref, left.total + right.max_pref)
        seg_tree[idx] = SegmentNode(total, min_pref, max_pref)

    build_tree(1, 0, N-1)

    output = []
    grad = 0
    for cmd in s:
        if cmd == 'L':
            if cursor > 0:
                cursor -= 1
            else:
                cursor -= 1
        elif cmd == 'R':
            cursor += 1
        else:
            if 0 <= cursor < N:
                text[cursor] = cmd
                update_tree(cursor, 0, N-1, 1)

        root = seg_tree[1]
        if root.total != 0 or root.min_pref < 0:
            output.append("-1")
        else:
            output.append(str(root.max_pref))

    print(" ".join(output))

